+    if (flag in flags) throw new CliError(`duplicate flag: ${flag}`);
+    const value = args[index + 1];
+    if (value === undefined || value.startsWith("--")) throw new CliError(`missing value for ${flag}`);
+    flags[flag] = value;
+  }
