import { afterEach, describe, expect, test } from "bun:test";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";

const directories: string[] = [];

async function run(args: string[], file: string) {
  const process = Bun.spawn(["bun", "run", "src/cli.ts", ...args], {
    cwd: join(import.meta.dir, ".."),
    env: { ...Bun.env, TASKBOARD_FILE: file },
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(process.stdout).text(),
    new Response(process.stderr).text(),
    process.exited,
  ]);
  return { exitCode, stdout, stderr, value: JSON.parse(stdout) };
}

async function freshFile() {
  const directory = await mkdtemp(join(tmpdir(), "taskboard-test-"));
  directories.push(directory);
  return join(directory, "nested", "tasks.json");
}

afterEach(async () => {
  await Promise.all(directories.splice(0).map((directory) => rm(directory, { recursive: true, force: true })));
});

describe("taskboard CLI", () => {
  test("persists, filters, completes, and reports stats", async () => {
    const file = await freshFile();
    const first = await run(["add", "--title", "First", "--tags", " Work,work, Urgent ", "--due", "2000-01-01"], file);
    expect(first.exitCode).toBe(0);
    expect(first.value).toMatchObject({ id: 1, title: "First", status: "open", tags: ["work", "urgent"], due: "2000-01-01" });

    const second = await run(["add", "--title", "Second", "--tags", "home"], file);
    expect(second.value.id).toBe(2);
    const filtered = await run(["list", "--status", "open", "--tag", "WORK", "--overdue", "2001-01-01"], file);
    expect(filtered.value.map((task: { id: number }) => task.id)).toEqual([1]);

    const completed = await run(["done", "1"], file);
    expect(completed.value.status).toBe("done");
    const completedAgain = await run(["done", "1"], file);
    expect(completedAgain.value.completedAt).toBe(completed.value.completedAt);

    const stats = await run(["stats"], file);
    expect(stats.value).toEqual({ total: 2, open: 1, done: 1, overdue: 0 });
    expect((await run(["delete", "2"], file)).value.id).toBe(2);
    expect((await run(["add", "--title", "Third"], file)).value.id).toBe(3);
  });

  test("rejects invalid input and preserves malformed data", async () => {
    const file = await freshFile();
    expect((await run(["add", "--title", "x", "--due", "2025-02-30"], file)).exitCode).not.toBe(0);
    await writeFile(file, "not json");
    const result = await run(["add", "--title", "safe"], file);
    expect(result.exitCode).not.toBe(0);
    expect(result.value.error).toContain("malformed");
    expect(await readFile(file, "utf8")).toBe("not json");
  });
});

